const hasActiveScreen=a=>!SCREEN_BREAKING_MOVES.has(a.moveId)&&a.attAbility!=='infiltrator'&&!a.critical&&((a.screen==='reflect'&&a.category==='physical')||(a.screen==='lightScreen'&&a.category==='special'));
